('ta-ss-02-hx-fouling-1', 'w-ss-02', 'tw-hx-fouling', 1, 1, array['valvepos','dpmodel']::text[], 'tubes', 'fouling', 'clean', array['r2']::text[], 12, 15, 80, true, true, 1, '{"checks":[{"id":"valvepos","verdict":"useful"},{"id":"dpmodel","verdict":"useful"}],"missed_checks":["intake"],"component":{"chosen":"tubes","correct":"tubes","right":true},"mode":{"chosen":"fouling","correct":"fouling","right":true},"action":{"chosen":"clean","best":"clean","verdict":"best"},"rationales":[{"id":"r2","sound":true}],"missed_rationales":["r1","r5"]}'::jsonb, '[{"code":"fs40_component","key":"m31.tw.reason.component"},{"code":"fs40_mode","key":"m31.tw.reason.mode"},{"code":"fs40_checks","key":"m31.tw.reason.checks","vars":{"useful":2,"total":3,"wasted":0}},{"code":"fs40_action_best","key":"m31.tw.reason.action.best"},{"code":"fs40_rationales","key":"m31.tw.reason.rationales","vars":{"sound":1,"total":3,"unsound":0}},{"code":"fs40_level","key":"m31.tw.reason.level","vars":{"level":1,"pct":80}}]'::jsonb, '[{"skill_id":"sk-fs-ai-twin","level":1},{"skill_id":"sk-fs-ai-plantdata","level":1}]'::jsonb, '2026-08-04T09:46:00Z'),
